def iso_at(days_ago: int, hour: int, minute: int) -> str:
    base = datetime(2026, 8, 13, hour, minute, tzinfo=NEPAL_TZ) - timedelta(days=days_ago)
    return base.isoformat()


def build_html(intro: str, heading: str, body: list[str], closing: str) -> str:
    parts = [f"<p>{intro}</p>", f"<h2>{heading}</h2>"]
    parts.extend(f"<p>{paragraph}</p>" for paragraph in body)
    parts.append(f"<p>{closing}</p>")
    return "".join(parts)


def png_bytes(width: int, height: int, rgb: tuple[int, int, int]) -> bytes:
    import struct

    row = bytes(rgb) * width
    raw = b"".join(b"\x00" + row for _ in range(height))

    def chunk(kind: bytes, data: bytes) -> bytes:
        return (
            struct.pack(">I", len(data))
            + kind
            + data
            + struct.pack(">I", zlib.crc32(kind + data) & 0xFFFFFFFF)
        )

    ihdr = struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0)
    return b"".join(
        [b"\x89PNG\r\n\x1a\n", chunk(b"IHDR", ihdr), chunk(b"IDAT", zlib.compress(raw, 9)), chunk(b"IEND", b"")]
    )


def ensure_placeholder(theme: str, bg_hex: str) -> Path:
    IMAGE_DIR.mkdir(parents=True, exist_ok=True)
    filename = theme.lower().replace(" ", "-") + ".png"
    path = IMAGE_DIR / filename
    if path.exists():
        return path
    url = f"https://placehold.co/1600x900/{bg_hex}/ffffff/png?text={quote(theme)}"
    try:
        response = requests.get(url, timeout=20)
        if response.ok and response.headers.get("content-type", "").startswith("image/"):
            path.write_bytes(response.content)
            return path
    except requests.RequestException:
        pass
    rgb = tuple(int(bg_hex[i : i + 2], 16) for i in (0, 2, 4))
    path.write_bytes(png_bytes(1600, 900, rgb))
    return path


