def make_article(
    title: str,
    slug: str,
    category_slug: str,
    excerpt: str,
    intro: str,
    heading: str,
    body: list[str],
    closing: str,
    image_theme: str,
    image_color: str,
    image_alt: str,
    status: str,
    published_at: str | None,
    featured: bool = False,
    breaking: bool = False,
) -> ArticleSeed:
    meta_title = title[:70]
    meta_description = excerpt[:170]
    return ArticleSeed(
        title,
        slug,
        excerpt,
        category_slug,
        build_html(intro, heading, body, closing),
        meta_title,
        meta_description,
        image_theme,
        image_color,
        image_alt,
        status,
        published_at,
        featured,
        breaking,
    )


