ARTICLES = [make_article(*spec) for spec in ARTICLE_SPECS]


class Seeder:
    def __init__(self, base_url: str, email: str, password: str) -> None:
        self.base_url = base_url
        self.email = email
        self.password = password
        self.session = requests.Session()
        self.image_urls: dict[str, str] = {}
        self.summary = {
            "categories_created": 0,
            "categories_updated": 0,
            "articles_created": 0,
            "articles_updated": 0,
            "images_uploaded": 0,
        }

    def request(self, method: str, path: str, **kwargs: object) -> requests.Response:
        return self.session.request(method, f"{self.base_url}{path}", timeout=60, **kwargs)

    def authenticate(self) -> None:
        csrf = self.request("GET", "/api/auth/csrf")
        csrf.raise_for_status()
        token = csrf.json()["csrfToken"]
        response = self.session.post(
            f"{self.base_url}/api/auth/callback/credentials",
            data={
                "csrfToken": token,
                "email": self.email,
                "password": self.password,
                "callbackUrl": f"{self.base_url}/admin",
                "json": "true",
            },
            headers={"X-Auth-Return-Redirect": "1"},
            timeout=60,
        )
        response.raise_for_status()
        session = self.request("GET", "/api/auth/session")
        session.raise_for_status()
        payload = session.json()
        if payload.get("user", {}).get("role") != "ADMIN":
            raise RuntimeError("Admin authentication failed.")

    def get_categories(self) -> list[dict[str, object]]:
        response = self.request("GET", "/api/categories")
        response.raise_for_status()
        return response.json()["data"]

    def get_admin_articles(self) -> list[dict[str, object]]:
        page = 1
        items: list[dict[str, object]] = []
        while True:
            response = self.request("GET", f"/api/articles?admin=true&limit=50&page={page}")
            response.raise_for_status()
            payload = response.json()
            items.extend(payload["data"])
            if not payload["meta"]["hasNextPage"]:
                return items
            page += 1

    def upsert_categories(self) -> dict[str, str]:
        current = self.get_categories()
        by_slug = {item["slug"]: item for item in current}
        by_name = {item["name"]: item for item in current}
        category_ids: dict[str, str] = {}

        for seed in CATEGORIES:
            payload = {
                "name": seed.name,
                "slug": seed.slug,
                "description": seed.description,
                "color": seed.color,
                "isActive": True,
                "sortOrder": seed.sort_order,
            }

            existing = by_slug.get(seed.slug) or by_name.get(seed.name)
            if existing is None:
                for legacy_slug, desired_slug in LEGACY_CATEGORY_SLUG_MAP.items():
                    if desired_slug != seed.slug:
                        continue
                    legacy = by_slug.get(legacy_slug)
                    if legacy and legacy.get("_count", {}).get("articles", 0) == 0:
                        existing = legacy
                        break

            if existing is None:
                created = self.request("POST", "/api/categories", json=payload)
                if created.status_code >= 400:
                    raise RuntimeError(f"Failed to create category {seed.slug}: {created.text}")
                body = created.json()["data"]
                category_ids[seed.slug] = body["id"]
                self.summary["categories_created"] += 1
                continue

            category_ids[seed.slug] = existing["id"]
            needs_update = any(
                [
                    existing["name"] != seed.name,
                    existing["slug"] != seed.slug,
                    (existing.get("description") or "") != seed.description,
                    (existing.get("color") or "") != seed.color,
                    existing["isActive"] is not True,
                    existing["sortOrder"] != seed.sort_order,
                ]
            )
            if not needs_update:
                continue

            updated = self.request("PATCH", f"/api/categories/{existing['id']}", json=payload)
            if updated.status_code >= 400:
                raise RuntimeError(f"Failed to update category {seed.slug}: {updated.text}")
            self.summary["categories_updated"] += 1

        return category_ids

    def upload_image(self, theme: str, color: str) -> str:
        if theme in self.image_urls:
            return self.image_urls[theme]

        path = ensure_placeholder(theme, color)
        with path.open("rb") as handle:
            response = self.session.post(
                f"{self.base_url}/api/uploads/images",
                files={"file": (path.name, handle, "image/png")},
                timeout=60,
            )
        if response.status_code >= 400:
            raise RuntimeError(f"Failed to upload image {theme}: {response.text}")
        url = response.json()["data"]["url"]
        self.image_urls[theme] = url
        self.summary["images_uploaded"] += 1
        return url

    def upsert_articles(self, category_ids: dict[str, str]) -> None:
        existing = {item["slug"]: item for item in self.get_admin_articles()}
        for seed in ARTICLES:
            payload = {
                "title": seed.title,
                "slug": seed.slug,
                "excerpt": seed.excerpt,
                "content": seed.html,
                "featuredImage": self.upload_image(seed.image_theme, seed.image_color),
                "featuredImageAlt": seed.image_alt,
                "youtubeUrl": None,
                "status": seed.status,
                "isFeatured": seed.featured,
                "isBreaking": seed.breaking,
                "categoryId": category_ids[seed.category_slug],
                "metaTitle": seed.meta_title,
                "metaDescription": seed.meta_description,
            }
            if seed.published_at is not None:
                payload["publishedAt"] = seed.published_at

            if seed.slug in existing:
                response = self.request("PATCH", f"/api/articles/{existing[seed.slug]['id']}", json=payload)
                if response.status_code >= 400:
                    raise RuntimeError(f"Failed to update article {seed.slug}: {response.text}")
                self.summary["articles_updated"] += 1
            else:
                response = self.request("POST", "/api/articles", json=payload)
                if response.status_code >= 400:
                    raise RuntimeError(f"Failed to create article {seed.slug}: {response.text}")
                self.summary["articles_created"] += 1

    def verify(self) -> dict[str, object]:
        admin_articles = self.get_admin_articles()
        public_articles = self.request("GET", "/api/articles?limit=50&sort=publishedAt&order=desc")
        featured = self.request("GET", "/api/articles?featured=true&limit=10")
        breaking = self.request("GET", "/api/articles?breaking=true&limit=10")
        category_view = self.request("GET", "/api/articles?category=paryatan&limit=10")
        slug_view = self.request("GET", f"/api/articles/slug/{ARTICLES[0].slug}")
        draft_view = self.request("GET", f"/api/articles/slug/{ARTICLES[-4].slug}")
        for response in [public_articles, featured, breaking, category_view, slug_view]:
            response.raise_for_status()
        image_url = slug_view.json()["data"]["featuredImage"]
        image_check = self.request("GET", image_url)
        image_check.raise_for_status()

        counts = {
            "admin_total": len(admin_articles),
            "published": sum(item["status"] == "PUBLISHED" for item in admin_articles),
            "draft": sum(item["status"] == "DRAFT" for item in admin_articles),
            "archived": sum(item["status"] == "ARCHIVED" for item in admin_articles),
            "featured": sum(bool(item["isFeatured"]) for item in admin_articles),
            "breaking": sum(bool(item["isBreaking"]) for item in admin_articles),
            "public_total": public_articles.json()["meta"]["total"],
            "featured_public_total": featured.json()["meta"]["total"],
            "breaking_public_total": breaking.json()["meta"]["total"],
            "tourism_public_total": category_view.json()["meta"]["total"],
            "draft_slug_status": draft_view.status_code,
            "image_status": image_check.status_code,
            "image_content_type": image_check.headers.get("content-type"),
        }

        if counts["published"] < 24 or counts["draft"] < 3 or counts["archived"] < 1:
            raise RuntimeError(f"Unexpected article state counts: {counts}")
        if counts["draft_slug_status"] != 404:
            raise RuntimeError("Draft article unexpectedly resolved on the public slug endpoint.")

        sample = slug_view.json()["data"]
        return {
            "counts": counts,
            "sample_article": {
                "title": sample["title"],
                "slug": sample["slug"],
                "category": sample["category"]["name"],
                "excerpt": sample["excerpt"],
            },
        }


def main() -> int:
    if not ADMIN_EMAIL or not ADMIN_PASSWORD:
        print("ADMIN_EMAIL and ADMIN_PASSWORD must be set in .env or the environment.", file=sys.stderr)
        return 1

    seeder = Seeder(BASE_URL, ADMIN_EMAIL, ADMIN_PASSWORD)
    seeder.authenticate()
    category_ids = seeder.upsert_categories()
    seeder.upsert_articles(category_ids)
    verification = seeder.verify()
    print(json.dumps({"baseUrl": BASE_URL, "summary": seeder.summary, "verification": verification}, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
